WITH valid_employees AS (SELECT * FROM employees WHERE job_title NOT IN ('Intern', 'Engineer', 'Analyst')), agg AS (SELECT job_title, SUM(CASE WHEN level = 'L4' THEN salary ELSE 0 END) AS l4_salary, ROUND((100 * SUM(CASE WHEN level = 'L3' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_l3 FROM valid_employees GROUP BY job_title) SELECT job_title, l4_salary, pct_l3 FROM agg ORDER BY job_title;
